//! Launching a subprocess engine turn (`Start-EngineProcess` / `Invoke-EngineTurn`,
//! `codex-consult.ps1:695-818`).
//!
//! One turn is: write the prompt where the engine expects it (per [`PromptDelivery`]),
//! spawn the launcher from the repo root with stdout redirected to the run's
//! `.events.jsonl`, stderr to a sidecar file, feed stdin, then wait up to `timeout`. On a
//! timeout the process tree is killed (Windows `taskkill /T`, Unix a plain kill of the
//! child) and the wall time is measured and rounded to one decimal exactly like the plugin
//! (`[math]::Round($watch.Elapsed.TotalSeconds, 1)`).
//!
//! This module is engine-agnostic: it delivers the prompt and captures the streams; parsing
//! the events into an [`crate::engines`] outcome is the engine adapter's job ([`super::codex`]).

use std::fs::File;
use std::io::{Read, Write};
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

use c3_core::engine::PromptDelivery;

/// One subprocess turn to run.
pub struct SpawnRequest<'a> {
    /// The resolved launcher path (may be a `.cmd`/`.bat` on Windows).
    pub launcher: &'a str,
    /// Everything after the launcher (already built by `c3_core::engine`).
    pub argv: &'a [String],
    /// The working directory (the git repo root).
    pub cwd: &'a Path,
    /// How the prompt reaches the engine; decides whether stdin carries it.
    pub prompt_delivery: PromptDelivery,
    /// The bytes to write to child stdin: the prompt for codex, the NDJSON line for agy,
    /// empty for muse (its prompt is the `--prompt-file` named in `argv`).
    pub stdin_text: &'a str,
    /// stdout is redirected here (the `.events.jsonl`).
    pub events_path: &'a Path,
    /// stderr is redirected here.
    pub stderr_path: &'a Path,
    /// The wall-clock budget for the turn.
    pub timeout: Duration,
    /// (wave 26b, D12) The stall cut in seconds (`0` = off): the turn is stopped like a timeout
    /// when its event stream produces no growth for this long while the process lives. Per wave
    /// 26c D3 the silent timer resets on any growth of the stream in bytes and is SUSPENDED while
    /// a tool call is in flight (see `tool_flight`).
    pub stall_sec: i64,
    /// (wave 26b, D10) The operator's kick file: when it appears the turn is stopped and recorded
    /// as `stopped by the operator (-Kick)`. `None` disables the check.
    pub kick_path: Option<&'a Path>,
    /// (wave 26c, D3 / 28b, D12) Classifies one event-stream line for the stall's tool-call
    /// suspension (`Update-ToolFlight`): a tool call OPENS (with its key and label), CLOSES, or the
    /// line is neutral. While a call is open the stall timer is suspended (bounded), and a stall cut
    /// names the open call(s). `None` = no suspension (the timer still resets on byte growth).
    pub tool_flight: Option<&'a dyn Fn(&str) -> ToolFlight>,
    /// Called once, right after the child is spawned and before it is waited on, with the
    /// child pid and its start time (.NET `o` string, or empty when unavailable). The
    /// orchestrator uses it to flip the recovery record `launching` -> `running` while the
    /// child is live (`codex-consult.ps1:3330-3339`).
    pub on_running: Option<&'a dyn Fn(u32, String)>,
    /// (wave 3e, F30-2) Called around a tree kill of this turn (the timeout, the stall cut, the
    /// kick): [`KillEvent::Before`] once the tree is enumerated and BEFORE anything is stopped -
    /// the orchestrator writes the recovery record that names it there, so a bridge that dies
    /// during the kill (or before the kill's result is recorded) leaves that record -, then
    /// [`KillEvent::After`] once the kill returned. `None`: nothing is told. (Wave 7, F30-2) The
    /// caller answers [`KillEvent::Before`] with what its write came to ([`KillRecord`]): the
    /// killer knows whether the evidence is on disk before it stops anything.
    pub on_kill: Option<&'a dyn Fn(KillEvent<'_>) -> KillRecord>,
    /// (0.6.0, wave 29, D2) The child's WHOLE environment (an allow list: claude) - the inherited
    /// environment is cleared and only these variables are set; `None` inherits this process's
    /// environment minus the host markers and the test-mode variables.
    pub env: Option<&'a [(String, String)]>,
    /// (wave 29) Quote the argv by the C runtime rules (`ConvertTo-CrtArg`): the claude schema
    /// TEXT travels in argv - on a batch launcher every argument goes through
    /// [`c3_core::claude::crt_arg`] verbatim.
    pub crt_quote: bool,
    /// (wave 8 = plugin wave 30, T15) The quota budget watch of a codex MAIN turn; `None`: off.
    pub budget: Option<&'a BudgetWatch>,
}

/// (wave 8 = plugin wave 30, T15) The quota budget of a codex turn (`Wait-EngineProcess
/// -BudgetPercent`): every `poll_ms` (15 s; the test hook `CODEX_CONSULT_TEST_BUDGET_POLL_MS`), once
/// the event stream names its thread, the 5-hour window of the thread's rollout under `codex_home` -
/// an observation of THIS turn (not older than its start) at `percent` or more, its reset ahead,
/// stops the turn like the stall cut ([`TurnStop::Budget`]).
#[derive(Debug, Clone)]
pub struct BudgetWatch {
    pub percent: i64,
    pub codex_home: String,
    pub poll_ms: u64,
}

impl BudgetWatch {
    /// The watch of a run's budget (`None` when it is off): the poll interval from the test hook
    /// (test mode only) or 15 s.
    pub fn of(percent: i64, codex_home: &str) -> Option<BudgetWatch> {
        if percent <= 0 {
            return None;
        }
        let poll_ms = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_BUDGET_POLL_MS")
            .and_then(|v| v.trim().parse::<u64>().ok())
            .filter(|v| *v > 0)
            .unwrap_or(c3_core::quota::BUDGET_POLL_MS);
        Some(BudgetWatch {
            percent,
            codex_home: codex_home.to_string(),
            poll_ms,
        })
    }
}

/// (wave 3e, F30-2) What a turn's tree kill tells its caller ([`SpawnRequest::on_kill`]).
#[derive(Debug)]
pub enum KillEvent<'a> {
    /// The tree is about to be killed: the root and its descendants from the kill's one read of the
    /// process table, each with the start time read then (`""` unreadable, `"<gone>"` exited
    /// meanwhile), or why they could not be enumerated. Nothing is stopped yet.
    Before {
        root: u32,
        tree: &'a Result<Vec<(u32, String)>, String>,
    },
    /// The kill returned (its check is known); the caller has not recorded its result yet.
    After,
}

/// (Wave 7, F30-2) What the caller's write at [`KillEvent::Before`] came to - told back to the
/// killer before it stops anything.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub enum KillRecord {
    /// Nothing was due ([`KillEvent::After`]; a caller that writes nothing).
    #[default]
    NotDue,
    /// The record that names the tree is on disk: in the recovery record or - that write failed -
    /// outside it (`fallback`: in its fallback file or - wave 7b - the codex home's copy, both
    /// read by the recovery too).
    Durable { fallback: bool },
    /// (Wave 7b, F38-1) Neither the recovery record, nor its fallback, nor the codex home's copy
    /// could be written (why: the three errors). NO KILL WITHOUT A RECORD: the tree is left alive
    /// as the evidence - the launch record on disk names its root, so the next run of the task is
    /// refused while it lives - and the turn ends as failed (its stop unchanged), the kill
    /// [`c3_core::engine::KillCheck::not_killed`].
    Lost(String),
}

/// (wave 3e, F30-2) A turn's kill hook as the engines carry it (see [`SpawnRequest::on_kill`]).
pub type KillHook = std::sync::Arc<dyn Fn(KillEvent<'_>) -> KillRecord + Send + Sync>;

/// Why [`run_turn`] stopped watching the child.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TurnStop {
    /// The child exited on its own.
    Exited,
    /// The wall-clock timeout fired and the tree was killed.
    Timeout,
    /// The stall cut fired (no event for `stall_sec` while the process lived) and the tree was killed.
    Stall,
    /// The operator's kick file appeared and the tree was killed.
    Kick,
    /// (wave 8 = plugin wave 30) The quota budget was reached and the tree was killed.
    Budget,
}

/// The result of one subprocess turn.
#[derive(Debug, Clone)]
pub struct TurnResult {
    /// Whether a process was actually started.
    pub started: bool,
    /// The child's exit code, or `None` when it was killed/timed out or never started.
    pub exit_code: Option<i32>,
    /// Why the watch ended (exited / timeout / stall / kick).
    pub stop: TurnStop,
    /// (wave 26c, D1) The process had already finished when a kick was found (checked once more
    /// after it exited): the kick is taken LATE (`kick_late`), the outcome unchanged.
    pub kick_late: bool,
    /// (wave 26b, D12) The ISO time of the last event-stream growth seen, `None` when none.
    pub last_event: Option<String>,
    /// (wave 26b, D12) Seconds without an event at the stall kill (`0` unless a stall fired).
    pub silent_seconds: i64,
    /// (wave 27c, D6) Seconds a tool call had been open at the stall kill (`0` when none was open);
    /// the stall outcome names it: `no output for N s (a tool call open for M s: <calls>)`.
    pub tool_open_seconds: i64,
    /// (wave 28b, D12) The tool call(s) open at the stall kill (`codex command_execution item_9`,
    /// `muse tool.shell t1`; several joined by `, `), `""` when none.
    pub open_tools: String,
    /// (wave 27c, D5) How many over-long unfinished lines (> 1 MiB with no line end) the bounded
    /// stream reader discarded during the turn; `0` normally. A non-zero count warns once per run.
    pub oversized_lines: u64,
    /// Pids that survived the kill (best-effort; empty when the tree died cleanly).
    pub survivors: Vec<u32>,
    /// (wave 27c D16, 28c D8, 28e E1/E23) What the tree kill could confirm (`None`: no kill).
    pub kill: Option<c3_core::engine::KillCheck>,
    /// Wall time, rounded to one decimal.
    pub wall_seconds: f64,
    /// The captured stderr text (UTF-8, lossily decoded).
    pub stderr: String,
    /// A launch error, when the process could not be started.
    pub error: Option<String>,
    /// (wave 8) The window that stopped the turn at its quota budget ([`TurnStop::Budget`]).
    pub budget: Option<c3_core::quota::PrimaryWindow>,
}

impl TurnResult {
    fn not_started(error: String) -> TurnResult {
        TurnResult {
            started: false,
            exit_code: None,
            stop: TurnStop::Exited,
            kick_late: false,
            last_event: None,
            silent_seconds: 0,
            tool_open_seconds: 0,
            open_tools: String::new(),
            oversized_lines: 0,
            survivors: Vec::new(),
            kill: None,
            wall_seconds: 0.0,
            stderr: String::new(),
            error: Some(error),
            budget: None,
        }
    }
}

/// (wave 27c, D5) The bounded stream reader's carry cap: the text after the last line end is kept
/// only up to 1 MiB; a longer unfinished line is discarded up to its end and counted.
const STREAM_CARRY_CAP: usize = 1024 * 1024;

/// (wave 27c, D6 / 28b, D12 / F36-11, F32-7) An open tool call cannot suspend the stall timer for
/// ever, and no completion event is needed to end the suspension: while a tool call is open the
/// stream must still GROW - once it has not grown for 2 x the stall seconds (no floor; the test hook
/// `CODEX_CONSULT_TEST_TOOL_CAP_SEC` = that bound) the suspension ends and the stall cut follows,
/// naming the open call.
fn tool_suspension_cap_secs(stall_sec: i64) -> i64 {
    if let Some(v) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_TOOL_CAP_SEC") {
        if let Ok(n) = v.trim().parse::<i64>() {
            if n > 0 {
                return n;
            }
        }
    }
    stall_sec.saturating_mul(2)
}

/// (wave 26c, D3 / 28b, D12) One event line's effect on the tool calls in flight
/// (`Update-ToolFlight`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ToolFlight {
    /// Not a tool call's start or end.
    None,
    /// A tool call starts: its key (a key ending in `#` is made unique by the tracker - a call
    /// without an id) and the label a stall cut names it by.
    Open { key: String, label: String },
    /// A tool call ends: the open call with `key`, else (none open by that key) the first open call
    /// whose key starts with `fallback_prefix` (`""` = none).
    Close {
        key: String,
        fallback_prefix: String,
    },
}

impl ToolFlight {
    /// The old count delta: `+1` open, `-1` close, `0` neutral.
    pub fn delta(&self) -> i64 {
        match self {
            ToolFlight::None => 0,
            ToolFlight::Open { .. } => 1,
            ToolFlight::Close { .. } => -1,
        }
    }
}

/// The tool calls in flight (a set by key, with their labels).
#[derive(Debug, Clone, Default)]
pub struct ToolCalls {
    open: Vec<(String, String)>,
    seq: u64,
}

impl ToolCalls {
    /// Apply one line's [`ToolFlight`].
    pub fn apply(&mut self, f: ToolFlight) {
        match f {
            ToolFlight::None => {}
            ToolFlight::Open { key, label } => {
                let key = if key.ends_with('#') {
                    self.seq += 1;
                    format!("{key}{}", self.seq)
                } else {
                    key
                };
                if !self.open.iter().any(|(k, _)| *k == key) {
                    self.open.push((key, label));
                }
            }
            ToolFlight::Close {
                key,
                fallback_prefix,
            } => {
                if !key.is_empty() {
                    if let Some(i) = self.open.iter().position(|(k, _)| *k == key) {
                        self.open.remove(i);
                        return;
                    }
                }
                if !fallback_prefix.is_empty() {
                    if let Some(i) = self
                        .open
                        .iter()
                        .position(|(k, _)| k.starts_with(&fallback_prefix))
                    {
                        self.open.remove(i);
                    }
                }
            }
        }
    }

    /// How many tool calls are open.
    pub fn count(&self) -> usize {
        self.open.len()
    }

    /// The open calls' labels, by key (ordinal), joined by `, ` (the plugin's `OpenTools`).
    pub fn labels(&self) -> String {
        let mut v: Vec<&(String, String)> = self.open.iter().collect();
        v.sort_by(|a, b| a.0.cmp(&b.0));
        v.iter()
            .map(|(_, l)| l.as_str())
            .collect::<Vec<_>>()
            .join(", ")
    }
}

fn round1(secs: f64) -> f64 {
    (secs * 10.0).round() / 10.0
}

/// `<kick file>.ack` â€” the acknowledgement the run writes for the `-Kick` command.
pub fn kick_ack_path(kick_path: &Path) -> std::path::PathBuf {
    let mut s = kick_path.as_os_str().to_os_string();
    s.push(".ack");
    std::path::PathBuf::from(s)
}

/// (Wave 7c, F40-2) The result of a kick taken on a live turn whose kill did not happen - its
/// record could be written nowhere ([`c3_core::engine::KillCheck::not_killed`]): the tree is left
/// alive as the evidence.
pub const KICK_NOT_KILLED: &str = "not killed";

/// One acknowledgement of a kick request (wave 27c, D1): the result (`stopped` | `late` | - wave
/// 7c, F40-2 - [`KICK_NOT_KILLED`]) and the request id it acknowledges; a `not killed` one names
/// the root pid left alive (`root`) and why (`reason`).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct KickAck {
    pub result: String,
    pub id: String,
    /// (Wave 7c, F40-2) `not killed`: the root pid of the tree left alive (`0`: none named).
    pub root: u32,
    /// (Wave 7c, F40-2) `not killed`: why (the kill's `why`, one line; `""`: none given).
    pub reason: String,
}

/// Parse the `id=<request id>` line of a kick file (wave 27c, D1). `None` when the file is absent
/// or carries no id.
pub fn read_kick_id(kick_path: &Path) -> Option<String> {
    let text = std::fs::read_to_string(kick_path).ok()?;
    for line in text.lines() {
        if let Some(v) = line.trim().strip_prefix("id=") {
            let v = v.trim();
            if !v.is_empty() {
                return Some(v.to_string());
            }
        }
    }
    None
}

/// Write the kick file atomically (temp file, then rename) so a caller never reads a half-written
/// request (wave 27c, D1). The file carries the request `id` and a human line.
pub fn write_kick_atomic(kick_path: &Path, id: &str) -> std::io::Result<()> {
    let body = format!(
        "id={id}\n{} -Kick from pid {}\n",
        iso_now(),
        std::process::id()
    );
    let mut tmp = kick_path.as_os_str().to_os_string();
    tmp.push(format!(".tmp-{}", std::process::id()));
    let tmp = std::path::PathBuf::from(tmp);
    std::fs::write(&tmp, body.as_bytes())?;
    // (D1) Publish WITHOUT overwriting: `hard_link` fails with `AlreadyExists` when the kick file
    // already exists, matching .NET's `File.Move` (which never overwrites). A second concurrent
    // -Kick caller therefore does NOT clobber the first's request â€” it re-reads and JOINS that id
    // (the caller's retry loop). `std::fs::rename` would silently replace on Windows, breaking that.
    let res = std::fs::hard_link(&tmp, kick_path);
    let _ = std::fs::remove_file(&tmp);
    res
}

/// Write `<kick>.ack` holding the result and the request id it acknowledges (wave 27c, D1);
/// (wave 7c, F40-2) `left`: the root pid left alive and why (`root=` / `reason=` lines, a
/// `not killed` acknowledgement).
pub fn write_kick_ack(kick_path: &Path, result: &str, id: &str, left: Option<(u32, &str)>) {
    let detail = left
        .map(|(root, why)| format!("root={root}\nreason={}\n", c3_core::one_line(why)))
        .unwrap_or_default();
    let _ = std::fs::write(
        kick_ack_path(kick_path),
        format!(
            "result={result}\n{detail}id={id}\n{} pid {}\n",
            iso_now(),
            std::process::id()
        ),
    );
}

/// Read `<kick>.ack` (wave 27c, D1). `None` when it is absent or unreadable.
pub fn read_kick_ack(ack_path: &Path) -> Option<KickAck> {
    let text = std::fs::read_to_string(ack_path).ok()?;
    let mut ack = KickAck::default();
    for line in text.lines() {
        let l = line.trim();
        if let Some(v) = l.strip_prefix("result=") {
            ack.result = v.trim().to_string();
        } else if let Some(v) = l.strip_prefix("id=") {
            ack.id = v.trim().to_string();
        } else if let Some(v) = l.strip_prefix("root=") {
            ack.root = v.trim().parse().unwrap_or(0);
        } else if let Some(v) = l.strip_prefix("reason=") {
            ack.reason = v.trim().to_string();
        }
    }
    Some(ack)
}

/// Sweep a stale acknowledgement (wave 27c, D1): remove `<kick>.ack` when it is older than
/// `max_age_secs` and its id is NOT `my_id` (a caller never sweeps its own live acknowledgement).
/// Best-effort; never fails.
pub fn sweep_stale_ack(kick_path: &Path, my_id: Option<&str>, max_age_secs: u64) {
    let ack_path = kick_ack_path(kick_path);
    let meta = match std::fs::metadata(&ack_path) {
        Ok(m) => m,
        Err(_) => return,
    };
    let age = meta
        .modified()
        .ok()
        .and_then(|m| m.elapsed().ok())
        .map(|d| d.as_secs())
        .unwrap_or(0);
    if age < max_age_secs {
        return;
    }
    if let Some(mine) = my_id {
        if read_kick_ack(&ack_path).map(|a| a.id).as_deref() == Some(mine) {
            return; // never sweep the caller's own acknowledgement
        }
    }
    let _ = std::fs::remove_file(&ack_path);
}

/// `Confirm-Kick` (wave 26c D1 / 27c D1): the member acknowledges the kick with `<kick>.ack`
/// holding the `result` (`stopped` | `late`) and the request id read from the kick file, then
/// removes the kick file. Never fails the run.
fn confirm_kick(kick_path: &Path, result: &str) {
    confirm_kick_with(kick_path, result, None);
}

/// [`confirm_kick`] with the tree left alive (`left`: its root pid and why) for a `not killed`
/// acknowledgement.
fn confirm_kick_with(kick_path: &Path, result: &str, left: Option<(u32, &str)>) {
    let id = read_kick_id(kick_path).unwrap_or_default();
    write_kick_ack(kick_path, result, &id, left);
    let _ = std::fs::remove_file(kick_path);
}

/// (Wave 7c, F40-2) The acknowledgement of a kick taken on a live turn, by what its kill did:
/// `stopped` - or, the kill did not happen ([`c3_core::engine::KillCheck::not_killed`]: its record
/// could be written nowhere and the tree is left alive as the evidence), [`KICK_NOT_KILLED`]
/// naming the root pid left alive and why. The `-Kick` command then reports the tree left alive
/// and fails.
fn acknowledge_taken_kick(kick_path: &Path, check: Option<&c3_core::engine::KillCheck>) {
    match check.filter(|c| c.not_killed) {
        Some(c) => confirm_kick_with(kick_path, KICK_NOT_KILLED, Some((c.root_pid, &c.why))),
        None => confirm_kick(kick_path, "stopped"),
    }
}

/// Whether a launcher is a Windows batch file (`.cmd` / `.bat`, any case).
pub fn is_batch_launcher(launcher: &str) -> bool {
    Path::new(launcher)
        .extension()
        .map(|e| {
            let e = e.to_string_lossy().to_ascii_lowercase();
            e == "cmd" || e == "bat"
        })
        .unwrap_or(false)
}

/// `ConvertTo-ProcArg`'s bare-token rule: `-` alone, or letters, digits and `_ . - : \ / =` only.
/// The plugin hands such an argument to the launcher as it is (no quotes).
pub fn is_bare_proc_arg(arg: &str) -> bool {
    arg == "-"
        || (!arg.is_empty()
            && arg.chars().all(|c| {
                c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-' | ':' | '\\' | '/' | '=')
            }))
}

/// How one argument reaches a batch launcher's command line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BatchArg {
    /// Appended verbatim (`CommandExt::raw_arg`): a bare token by the plugin's rule.
    Raw(String),
    /// Left to Rust std's batch-file escaping (quoted, `"` doubled, `%` neutralised, a line break
    /// refused).
    Std(String),
}

/// (wave 2b, the launcher quoting) The arguments of a batch launcher (`codex.cmd`, an npm shim, the
/// harness fakes) as the plugin's `Start-Process -ArgumentList` hands them over
/// (`ConvertTo-ProcArg`): a bare token (`-c`, `model_context_window=256000`, `-p=`, a plain path)
/// goes as it is - Rust std's own batch escaping would quote every argument holding `=`
/// (`"model_context_window=256000"`, `"-p="`), which a launcher matching its `%*` text then does
/// not see. Everything else (spaces, quotes, `%`, other symbols) keeps std's escaping: quoted with
/// every `"` doubled - the plugin's form - plus std's guards against `%VAR%` expansion and line
/// breaks, which the plugin lacks.
pub fn batch_args(argv: &[String]) -> Vec<BatchArg> {
    argv.iter()
        .map(|a| {
            if is_bare_proc_arg(a) {
                BatchArg::Raw(a.clone())
            } else {
                BatchArg::Std(a.clone())
            }
        })
        .collect()
}

/// Put `argv` on the launcher's command. The launcher path is always the program and the caller's
/// `argv` are always the args - including for a Windows `.cmd`/`.bat` launcher. We deliberately do
/// **not** wrap a batch launcher in an explicit `cmd /c`: doing so makes `cmd.exe` the program (an
/// `.exe`), so Rust escapes the embedded quotes in each arg the MSVC way (`model_provider=\"ZAI\"`),
/// which is not what a batch file's `%*` expander produces. Handing the `.cmd`/`.bat` path straight
/// to `Command` lets Rust std run it through `cmd.exe` (the child pid is still `cmd.exe`'s, so
/// `kill_tree`/`on_running` are unchanged); the arguments follow [`batch_args`]. An `.exe`
/// launcher's escaping is untouched.
pub fn apply_launcher_args(cmd: &mut Command, launcher: &str, argv: &[String]) {
    apply_launcher_args_quoted(cmd, launcher, argv, false)
}

/// [`apply_launcher_args`] with the C runtime quoting of a claude turn (`crt`): a batch launcher
/// gets every argument as `ConvertTo-CrtArg` writes it (the plugin's `Start-Process` argument
/// string), an `.exe` Rust std's own MSVC quoting - which is the C runtime's.
pub fn apply_launcher_args_quoted(cmd: &mut Command, launcher: &str, argv: &[String], crt: bool) {
    #[cfg(windows)]
    {
        if crt && is_batch_launcher(launcher) {
            use std::os::windows::process::CommandExt;
            for a in argv {
                cmd.raw_arg(c3_core::claude::crt_arg(a));
            }
            return;
        }
        if is_batch_launcher(launcher) {
            use std::os::windows::process::CommandExt;
            for a in batch_args(argv) {
                match a {
                    BatchArg::Raw(v) => {
                        cmd.raw_arg(v);
                    }
                    BatchArg::Std(v) => {
                        cmd.arg(v);
                    }
                }
            }
            return;
        }
    }
    let _ = launcher;
    cmd.args(argv);
}

/// Run one subprocess turn (spawn, feed stdin, capture streams, wait with a timeout kill).
pub fn run_turn(req: &SpawnRequest) -> TurnResult {
    let stdout_file = match File::create(req.events_path) {
        Ok(f) => f,
        Err(e) => return TurnResult::not_started(format!("could not open the events file: {e}")),
    };
    let stderr_file = match File::create(req.stderr_path) {
        Ok(f) => f,
        Err(e) => return TurnResult::not_started(format!("could not open the stderr file: {e}")),
    };

    let program = req.launcher.to_string();
    let mut cmd = Command::new(&program);
    apply_launcher_args_quoted(&mut cmd, req.launcher, req.argv, req.crt_quote);
    cmd.current_dir(req.cwd)
        .stdin(Stdio::piped())
        .stdout(Stdio::from(stdout_file))
        .stderr(Stdio::from(stderr_file));
    // (wave 29, D2) an allow-listed environment replaces the inherited one
    if let Some(env) = req.env {
        cmd.env_clear();
        for (k, v) in env {
            cmd.env(k, v);
        }
    }
    // (wave 27 / 27b) the reviewer CLI never inherits the coordinator's host markers.
    super::scrub_host_markers(&mut cmd);

    let mut child: Child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return TurnResult::not_started(format!("could not start {program}: {e}")),
    };

    // Register the running child (recovery record `launching` -> `running`) before it is
    // waited on. The pid is the launcher's; on Windows the real codex is a descendant of the
    // `cmd /c` wrapper, so a mid-run crash leaves the record naming this pid and the next run
    // scans the tree â€” matching the plugin recording `$proc.Id`.
    if let Some(cb) = req.on_running {
        let pid = child.id();
        let start = crate::liveness::proc::process_start_iso(pid).unwrap_or_default();
        cb(pid, start);
    }

    // Feed stdin. muse gets an empty stdin; codex/agy get their text. Closing the handle
    // (drop) sends EOF so the child's ReadToEnd returns.
    if let Some(mut stdin) = child.stdin.take() {
        // A muse turn writes nothing (its prompt is a file) â€” still close stdin.
        if !matches!(req.prompt_delivery, PromptDelivery::PromptFile) {
            let _ = stdin.write_all(req.stdin_text.as_bytes());
        }
        // drop closes stdin
    }

    let start = Instant::now();
    let mut stop = TurnStop::Exited;
    let mut kick_late = false;
    let mut survivors = Vec::new();
    let mut kill_check: Option<c3_core::engine::KillCheck> = None;
    // Stall tracking (wave 26b D12 + 26c D3): byte offset consumed so far, the last time the
    // stream grew, the count of tool calls currently in flight, and the last event time seen.
    let stall_on = req.stall_sec > 0;
    let mut offset: u64 = 0;
    let mut line_buf = String::new();
    let mut last_activity = Instant::now();
    let mut open_tools = ToolCalls::default();
    let mut open_tool_labels = String::new();
    let mut last_event: Option<String> = None;
    let mut silent_seconds: i64 = 0;
    let mut tool_open_seconds: i64 = 0;
    // (wave 27c, D5) over-long unfinished lines discarded, and whether we are skipping the tail of
    // one until its line end. (wave 27c, D6) when the current tool-call suspension began.
    let mut oversized_lines: u64 = 0;
    let mut discarding = false;
    let mut tool_open_since: Option<Instant> = None;
    // (wave 8 = plugin wave 30) the quota budget watch: the thread (from the stream's head), its
    // rollout, the next poll and the turn's start (an observation older than it never stops it)
    let mut budget_hit: Option<c3_core::quota::PrimaryWindow> = None;
    let mut budget_thread = String::new();
    let mut budget_rollout: Option<std::path::PathBuf> = None;
    let mut next_budget_ms: u64 = req.budget.map(|b| b.poll_ms).unwrap_or(0);
    let turn_start = (chrono::Utc::now() - chrono::Duration::seconds(2)).fixed_offset();
    let kill_now = |child: &mut Child| -> (Vec<u32>, Option<c3_core::engine::KillCheck>) {
        // (wave 27c D16, 28c D8, 28e E1/E23) the tree kill, CONFIRMED (`Stop-ProcessTreeChecked`):
        // the survivors it saw, the descendants it could not verify, why it is not confirmed.
        // CODEX_CONSULT_TEST_KILL_DENIED=1 (test mode) simulates a restricted host - the children
        // cannot be enumerated and taskkill fails: only the root is stopped, its children are left
        // running as orphans and the kill is not confirmed.
        // (wave 3e, F30-2) the caller writes the record that names the tree BEFORE the kill
        let (mut s, check) = kill_tree_checked(child, req.on_kill);
        // TEST HOOK: CODEX_CONSULT_TEST_SURVIVORS=<pid>[,<pid>] â€” these pids, when alive, are
        // reported as survivors of this kill (no test can make a real process outlive a kill).
        // Only ever adds (a stricter outcome), matching `$env:CODEX_CONSULT_TEST_SURVIVORS`.
        for hook in test_survivor_pids() {
            if crate::liveness::proc::pid_alive(hook, "") && !s.contains(&hook) {
                s.push(hook);
            }
        }
        if let Some(cb) = req.on_kill {
            let _ = cb(KillEvent::After);
        }
        (s, Some(check))
    };
    // (wave 26c, D1) a kick that arrived before the wait loop, on a live turn, is taken at once.
    if let Some(kp) = req.kick_path {
        if kp.exists() {
            match child.try_wait() {
                Ok(Some(_)) => {} // already exited â€” handled after the loop as a late kick
                _ => {
                    (survivors, kill_check) = kill_now(&mut child);
                    stop = TurnStop::Kick;
                    acknowledge_taken_kick(kp, kill_check.as_ref());
                }
            }
        }
    }
    let exit_code = if stop == TurnStop::Kick {
        // A kick was taken before the loop; do not wait.
        None
    } else {
        loop {
            match child.try_wait() {
                Ok(Some(status)) => break status.code(),
                Ok(None) => {
                    if start.elapsed() >= req.timeout {
                        (survivors, kill_check) = kill_now(&mut child);
                        stop = TurnStop::Timeout;
                        break None;
                    }
                    // (wave 26b, D10 / 26c D1) the operator's kick, checked on every poll; on a live
                    // turn it is taken at once and acknowledged.
                    if let Some(kp) = req.kick_path {
                        if kp.exists() {
                            (survivors, kill_check) = kill_now(&mut child);
                            stop = TurnStop::Kick;
                            acknowledge_taken_kick(kp, kill_check.as_ref());
                            break None;
                        }
                    }
                    // (wave 8 = plugin wave 30, T15) the quota budget.
                    if let Some(b) = req.budget {
                        let el = start.elapsed().as_millis() as u64;
                        if b.percent > 0 && el >= next_budget_ms {
                            next_budget_ms = el + b.poll_ms;
                            if budget_thread.is_empty() {
                                budget_thread =
                                    c3_core::quota::thread_id_from_stream_head(req.events_path);
                            }
                            if !budget_thread.is_empty() && budget_rollout.is_none() {
                                budget_rollout = c3_core::quota::codex_rollout_path(
                                    &budget_thread,
                                    &b.codex_home,
                                );
                            }
                            if let Some(rp) = &budget_rollout {
                                let w = c3_core::quota::read_primary_window(Some(rp));
                                if c3_core::quota::budget_reached(
                                    &w,
                                    b.percent,
                                    turn_start,
                                    chrono::Utc::now(),
                                ) {
                                    budget_hit = Some(w);
                                    (survivors, kill_check) = kill_now(&mut child);
                                    stop = TurnStop::Budget;
                                    break None;
                                }
                            }
                        }
                    }
                    // (wave 26b, D12 / 26c D3 / 27c D5+D6) the stall cut.
                    if stall_on {
                        let grew = read_stream_growth(
                            req.events_path,
                            &mut offset,
                            &mut line_buf,
                            req.tool_flight,
                            &mut open_tools,
                            &mut oversized_lines,
                            &mut discarding,
                        );
                        if grew {
                            last_activity = Instant::now();
                            last_event = Some(iso_now());
                        }
                        // (wave 27c, D6) track when the current tool-call suspension began.
                        if open_tools.count() > 0 {
                            tool_open_since.get_or_insert_with(Instant::now);
                        } else {
                            tool_open_since = None;
                        }
                        let silent = last_activity.elapsed().as_secs() as i64;
                        // The timer is suspended while a tool call is in flight â€” but only up to
                        // 2 x stall with no growth of the stream at all (wave 28b D12).
                        let fire = if open_tools.count() == 0 {
                            silent >= req.stall_sec
                        } else {
                            silent >= tool_suspension_cap_secs(req.stall_sec)
                        };
                        if fire {
                            silent_seconds = silent;
                        tool_open_seconds: 0,
                        open_tools: String::new(),
                        oversized_lines,
                        survivors: Vec::new(),
                        kill: None,
                        wall_seconds: round1(start.elapsed().as_secs_f64()),
                        stderr: read_text(req.stderr_path),
                        kick_late: false,
                        error: Some(format!("waiting on the child failed: {e}")),
                        budget: None,
                    };
                }
            }
        }
    };
    // (wave 26c, D1) check once more after the process ended on its own: a kick found now had no
    // live turn to stop â€” it is taken LATE (the outcome is unchanged), acknowledged as `late`.
    if stop == TurnStop::Exited {
        if let Some(kp) = req.kick_path {
            if kp.exists() {
                kick_late = true;
                confirm_kick(kp, "late");
            }
        }
    }
    let wall_seconds = round1(start.elapsed().as_secs_f64());

    // (wave 27c, D5) one warning per run when an over-long unfinished line was discarded.
    if oversized_lines > 0 {
        eprintln!(
            "codex-consult: {oversized_lines} over-long unfinished line(s) (> 1 MiB) were discarded from the event stream"
        );
    }

    TurnResult {
        started: true,
        exit_code,
        stop,
        kick_late,
        last_event,
        silent_seconds,
        tool_open_seconds,
        open_tools: open_tool_labels,
        oversized_lines,                    chunk = chunk[nl + 1..].to_string();
                }
                None => return true, // still no line end â€” keep discarding; the stream grew
            }
        }
        line_buf.push_str(&chunk);
        while let Some(nl) = line_buf.find('\n') {
            let line: String = line_buf.drain(..=nl).collect();

            Err(_) => return true,
        }
        if Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
}

/// (wave 27c D16; 28b D14; 28c D8; 28e E1/E23) `Stop-ProcessTreeChecked`: kill the process AND its
/// descendants (the launcher is usually a shim: cmd.exe or node in front of the real codex), and
/// say what the kill could confirm. Windows: `taskkill /T /F` first, then the root by its handle,
/// then every descendant whose identity is confirmed (the start time read at the enumeration
/// matches the one read now) by its pid; elsewhere the root and the descendants by pid. The killed
/// pids are polled (100 ms steps, up to 3 s): only those still alive then are survivors (a process
/// merely still exiting is none). A descendant whose start time cannot be read is neither killed by
/// its pid nor counted as gone - it is listed as unverified and the kill is "not confirmed: start
/// time of pid <n> unreadable". When the children cannot be enumerated (a restricted host) the kill
/// falls back to `taskkill /T /F` once more while the root is still there; the kill is then
/// confirmed only when the root exited AND taskkill reported success (outside Windows never).
/// (wave 3e, F30-2) `on_kill` hears [`KillEvent::Before`] once the tree is enumerated, before
/// anything is stopped; (wave 7) its answer comes back here. (Wave 7b, F38-1) NO KILL WITHOUT A
/// RECORD: a record written nowhere - neither to the recovery record, nor to its fallback, nor to
/// the codex home's copy ([`KillRecord::Lost`]) - leaves the tree ALIVE as the evidence: nothing is
/// stopped, the survivors are the root and its live descendants, the kill is not confirmed and
/// [`c3_core::engine::KillCheck::not_killed`] (`the kill record could not be written anywhere
/// (<why>): the reviewer tree (pid <root>) is left alive as the evidence; the task is refused until
/// it is gone or recorded`). TEST HOOK (test mode only): `CODEX_CONSULT_TEST_KILL_SPARE=<file>` -
/// the pids that file names (read at the kill; separated by whitespace or commas) stand for a
/// helper the kill cannot stop: they are not stopped by pid and no `taskkill /T` runs over the tree
/// (it would reach them). Returns `(survivors, check)`.
fn kill_tree_checked(
    child: &mut Child,
    on_kill: Option<&dyn Fn(KillEvent<'_>) -> KillRecord>,
) -> (Vec<u32>, c3_core::engine::KillCheck) {
    use crate::liveness::proc::{pid_identity, PidIdentity};
    let root = child.id();
    let tree = descendant_tree(root);
    let record = on_kill
        .map(|cb| cb(KillEvent::Before { root, tree: &tree }))
        .unwrap_or_default();
    let (descendants, denied) = match tree {
        Ok(d) => (d, String::new()),
        Err(why) => (Vec::new(), why),
    };
    if let KillRecord::Lost(why) = record {
        return left_alive(child, &descendants, &why);
    }
    let spared = kill_spared_pids();
    #[cfg(windows)]
    let mut taskkill_exit = if spared.is_empty() {
        taskkill_tree(root)
    } else {
        1
    };
    #[cfg(not(windows))]
    let taskkill_exit = -1;
    // The root before its descendants: a root that outlives its children reacts to their death (a
    // shell or node shim carries on and may start new processes).
    let _ = child.kill();
    for (d, st0) in &descendants {
        // (wave 28b, D14) never a pid that meanwhile belongs to another process; (wave 28c, D8)
        // never one whose identity cannot be confirmed
        if st0 == "<gone>" || spared.contains(d) || pid_identity(*d, st0) != PidIdentity::Alive {
            continue;
        }
        crate::liveness::proc::terminate_pid(*d);
    }
    let _ = root_exited_within(child, 10_000);
    // The root by its handle; a descendant counts as alive only while a process with its pid exists
    // WITH the start time read at the enumeration; one whose start time cannot be read is unknown.
    let deadline = Instant::now() + Duration::from_secs(3);
    let mut alive: Vec<u32>;
    let mut unknown: Vec<u32>;
    let mut root_gone;
    loop {
        alive = Vec::new();
        unknown = Vec::new();
        root_gone = root_exited_within(child, 0);
        if !root_gone {
            alive.push(root);
        }
        for (d, st) in &descendants {
            if st == "<gone>" {
                continue;
            }
            match pid_identity(*d, st) {
                PidIdentity::Alive => alive.push(*d),
                PidIdentity::Unknown => unknown.push(*d),
                PidIdentity::Gone => {}
            }
        }
        if (alive.is_empty() && unknown.is_empty()) || Instant::now() >= deadline {
            break;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    let mut check = c3_core::engine::KillCheck::confirmed(root);
    if !unknown.is_empty() {
        check.confirmed = false;
        check.why = format!(
            "start time of pid {} unreadable",
            unknown
                .iter()
                .map(|p| p.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        );
        check.unverified = unknown;
    }
    if !denied.is_empty() {
        // the children are not known: the fallback taskkill once more when the root is still
        // there, then the root checked again
        #[cfg(windows)]
        if !root_gone {
            taskkill_exit = taskkill_tree(root);
            root_gone = root_exited_within(child, 3_000);
            if root_gone {
                alive.retain(|p| *p != root);
            }
        }
        if !root_gone {
            check.confirmed = false;
            check.why = format!(
                "the children could not be enumerated ({denied}) and the root process did not exit"
            );
        } else if !cfg!(windows) || taskkill_exit != 0 {
            check.confirmed = false;
            let taskkill = if cfg!(windows) {
                format!(" and taskkill /T /F failed (exit {taskkill_exit})")
            } else {
                String::new()
            };
            check.why = format!(
                "the children could not be enumerated ({denied}){taskkill} - the root exited, its children may not have"
            );
        }
    }
    if !alive.is_empty() {
        check.confirmed = false;
    }
    (alive, check)
}

/// (Wave 7b, F38-1) The kill that does not happen - its record could be written nowhere (`why`):
/// the tree is left alive as the evidence. Its survivors are the root and the descendants of the
/// enumeration still alive with the start time read then; one whose start time cannot be read is
/// unverified. Not confirmed, `not_killed`.
fn left_alive(
    child: &mut Child,
    descendants: &[(u32, String)],
    why: &str,
) -> (Vec<u32>, c3_core::engine::KillCheck) {
    use crate::liveness::proc::{pid_identity, PidIdentity};
    let root = child.id();
    let mut alive: Vec<u32> = Vec::new();
    let mut unknown: Vec<u32> = Vec::new();
    if !root_exited_within(child, 0) {
        alive.push(root);
    }
    for (d, st) in descendants {
        if st == "<gone>" {
            continue;
        }
        match pid_identity(*d, st) {
            PidIdentity::Alive => alive.push(*d),
            PidIdentity::Unknown => unknown.push(*d),
            PidIdentity::Gone => {}
        }
    }
    let check = c3_core::engine::KillCheck {
        root_pid: root,
        confirmed: false,
        why: format!(
            "the kill record could not be written anywhere ({why}): the reviewer tree (pid {root}) is left alive as the evidence; the task is refused until it is gone or recorded"
        ),
        unverified: unknown,
        not_killed: true,
    };
    (alive, check)
}

/// (Wave 7b, F38-1) TEST HOOK (test mode only): `CODEX_CONSULT_TEST_KILL_SPARE=<file>` - the pids
/// the file names, read at the kill (empty: none, or the file cannot be read).
fn kill_spared_pids() -> Vec<u32> {
    let Some(file) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_KILL_SPARE") else {
        return Vec::new();
    };
    let file = file.trim();
    if file.is_empty() {
        return Vec::new();
    }
    std::fs::read_to_string(file)
        .unwrap_or_default()
        .split(|c: char| c.is_whitespace() || c == ',')
        .filter_map(|t| t.trim().parse::<u32>().ok())
        .collect()
}

/// `kill -9 <pid>` through the `kill` binary (no libc dependency); best effort.
#[cfg(not(windows))]
fn kill_pid_unix(pid: u32) {
    let _ = Command::new("kill")
        .args(["-9", &pid.to_string()])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
}

/// Kill the process tree rooted at `pid` (a tree WE started, by pid â€” never by name). On Windows
/// `taskkill /F /T /PID <pid>`; on Unix a best-effort `kill`. Used by the registration-failure path
/// where only the child pid is known (the `Child` handle is owned by the running turn).
pub fn kill_tree_by_pid(pid: u32) {
    if pid == 0 {
        return;
    }
    #[cfg(windows)]
    {
        let _ = Command::new("taskkill")
            .args(["/F", "/T", "/PID", &pid.to_string()])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
    }
    #[cfg(not(windows))]
    {
        for d in crate::liveness::proc::descendants_of(pid) {
            kill_pid_unix(d);
        }
        kill_pid_unix(pid);
    }
}

/// The pids named by `CODEX_CONSULT_TEST_SURVIVORS` (comma-separated), for the survivor hook.
fn test_survivor_pids() -> Vec<u32> {
    c3_core::test_hooks::hook("CODEX_CONSULT_TEST_SURVIVORS")
        .map(|v| {
            v.split(',')
                .filter_map(|s| s.trim().parse::<u32>().ok())
                .filter(|p| *p > 0)
                .collect()
        })
        .unwrap_or_default()
}

fn read_text(path: &Path) -> String {
    let mut s = Vec::new();
    if let Ok(mut f) = File::open(path) {
        let _ = f.read_to_end(&mut s);
    }
    String::from_utf8_lossy(&s).to_string()
}

