260: /// The verdict on one detached run.
261: #[derive(Debug, Clone)]
262: pub struct Judgement {
263:     /// `done` | `running` | `elsewhere` | `starting` | `died` | `never-started` | `unreadable`.
264:     pub state: String,
265:     pub exit: i32,
266:     pub text: String,
267:     pub finished: i64,
268:     pub of: i64,
269: }
270: 
271: /// `Get-DetachedJudgement` (D5, D6, D11). `problem` is a non-empty read error (unreadable);
272: /// `record` is `None` when the file was absent. `machine_name` is this host's name (for the
273: /// other-host check).
274: pub fn judgement(
275:     record: Option<&DetachedRecord>,
276:     problem: &str,
277:     now: DateTime<Utc>,
278:     machine_name: &str,
279: ) -> Judgement {
280:     let record = match (problem.is_empty(), record) {
281:         (true, Some(r)) => r,
282:         _ => {
283:             let text = if problem.is_empty() {
284:                 "no status record".to_string()
285:             } else {
286:                 problem.to_string()
287:             };
288:             return Judgement {
289:                 state: "unreadable".into(),
290:                 exit: 1,
291:                 text,
292:                 finished: 0,
293:                 of: 0,
294:             };
295:         }
296:     };
297:     let members: Vec<&DetachedMember> = record.members.iter().collect();
298:     let of = members
299:         .iter()
300:         .filter(|m| m.state != "skipped" || is_not_started(m))
301:         .count() as i64;
302:     let finished = members
303:         .iter()
304:         .filter(|m| MEMBER_DONE.contains(&m.state.as_str()) || is_not_started(m))
305:         .count() as i64;
306:     let started = record.started.as_deref().and_then(parse_when);
307:     let started_text = record
308:         .started
309:         .as_deref()
310:         .filter(|s| !s.is_empty())
311:         .unwrap_or("(unknown)");
312: 
313:     if record.state == "done" {
314:         let exit_text = record
315:             .exit
316:             .map(|c| c.to_string())
317:             .unwrap_or_else(|| "unknown".into());
318:         let ok = record.exit == Some(0);
319:         return Judgement {
320:             state: "done".into(),
321:             exit: if ok { 0 } else { 1 },
322:             text: format!("done, exit {exit_text}"),
323:             finished,
324:             of,
325:         };
326:     }
327: 
328:     let bg_pid = record.pid.unwrap_or(0);
329:     if bg_pid <= 0 {
330:         let age_secs = started
331:             .map(|s| (now - s.with_timezone(&Utc)).num_seconds())
332:             .unwrap_or(i64::MAX);
333:         if age_secs < START_GRACE_SEC {
334:             return Judgement {
335:                 state: "starting".into(),
336:                 exit: 2,
337:                 text: format!(
338:                     "starting - the background has not reported yet (started {} ago)",
339:                     format_span(age_secs.max(0) as f64)
340:                 ),
341:                 finished,
342:                 of,
343:             };
344:         }
345:         return Judgement {
346:             state: "never-started".into(),
347:             exit: 1,
348:             text: format!(
349:                 "never started - no background process reported within {START_GRACE_SEC} s of {started_text}; if one starts late it still reports and the run reads running again (its log may say why)"
350:             ),
351:             finished,
352:             of,
353:         };
354:     }
355: 
356:     if !record.host.is_empty() && !record.host.eq_ignore_ascii_case(machine_name) {
357:         return Judgement {
358:             state: "elsewhere".into(),
359:             exit: 2,
360:             text: format!(
361:                 "running on host {} since {started_text} (pid {bg_pid}) - its liveness cannot be checked from this host",
362:                 record.host
363:             ),
364:             finished,
365:             of,
366:         };
367:     }
368: 
369:     let start_time = record.start_time.clone().unwrap_or_default();
370:     if pid_alive(bg_pid as u32, &start_time) {
371:         let since = started
372:             .map(|s| {
373:                 format!(
374:                     " ({})",
375:                     format_span((now - s.with_timezone(&Utc)).num_seconds().max(0) as f64)
376:                 )
377:             })
378:             .unwrap_or_default();
379:         return Judgement {
380:             state: "running".into(),
381:             exit: 2,
382:             text: format!(
383:                 "running since {started_text}{since}, {finished} of {of} members finished"
384:             ),
385:             finished,
386:             of,
387:         };
388:     }
389:     Judgement {
390:         state: "died".into(),
391:         exit: 1,
392:         text: format!(
393:             "died - its background process (pid {bg_pid}) is gone without a final status, {finished} of {of} members finished; its recovery records are judged by the next run of the task as usual"
394:         ),
395:         finished,
396:         of,
397:     }
398: }
