1049: /// `Read-DetachedRuns`: every detached run of a task directory, newest first (by `started`, else
1050: /// the file's last-write; then id8 ascending).
1051: fn read_detached_runs(task_dir: &Path) -> Vec<RunEntry> {
1052:     let mut runs: Vec<RunEntry> = Vec::new();
1053:     let rd = match std::fs::read_dir(task_dir) {
1054:         Ok(rd) => rd,
1055:         Err(_) => return runs,
1056:     };
1057:     for entry in rd.flatten() {
1058:         let name = entry.file_name().to_string_lossy().to_string();
1059:         let id8 = match parse_status_name(&name) {
1060:             Some(v) => v,
1061:             None => continue,
1062:         };
1063:         let path = entry.path();
1064:         let (record, error) = match read_detached_status(&path) {
1065:             Ok(r) => (r, String::new()),
1066:             Err(e) => (None, e),
1067:         };
1068:         let when = record
1069:             .as_ref()
1070:             .and_then(|r| r.started.as_deref())
1071:             .and_then(parse_when)
1072:             .map(|d| d.with_timezone(&Utc))
1073:             .or_else(|| {
1074:                 std::fs::metadata(&path)
1075:                     .and_then(|m| m.modified())
1076:                     .ok()
1077:                     .map(chrono::DateTime::<Utc>::from)
1078:             })
1079:             .unwrap_or_else(|| chrono::DateTime::<Utc>::from(std::time::UNIX_EPOCH));
1080:         let log = task_dir.join(format!(".consult.detached-{id8}.log"));
1081:         runs.push(RunEntry {
1082:             path,
1083:             id8,
1084:             record,
1085:             error,
1100:     } else {
1101:         None
1102:     }
