1111: pub fn query(o: &Options) -> i32 {
1112:     if o.detach {
1113:         return status_query_refusal(
1114:             "-Detach does not go with -Status or -Wait: -Detach starts a consultation, -Status and -Wait look at detached ones.",
1115:         );
1116:     }
1117:     // Only the query options are allowed (`codex-consult.ps1:1103`). Which ones were "given" is
1118:     // known from the *_given flags and the non-empty run fields (the shim forwards only bound
1119:     // parameters for a query).
1120:     let mut extra: Vec<&str> = Vec::new();
1121:     if !o.mode.is_empty() {
1122:         extra.push("Mode");
1123:     }
1124:     if !o.thread.is_empty() {
1125:         extra.push("Thread");
1126:     }
1127:     if !o.brief.is_empty() {
1128:         extra.push("Brief");
1129:     }
1130:     if !o.prompt.is_empty() {
1131:         extra.push("Prompt");
1132:     }
1133:     if !o.provider.is_empty() {
1134:         extra.push("Provider");
1135:     }
1136:     if !o.model.is_empty() {
1137:         extra.push("Model");
1138:     }
1139:     if !o.purpose.is_empty() {
1140:         extra.push("Purpose");
1141:     }
1142:     if o.panel || o.panel_all {
1143:         extra.push("Panel");
1144:     }
1145:     if !o.engine.is_empty() {
1146:         extra.push("Engine");
1147:     }
1148:     if !extra.is_empty() {
1149:         extra.sort_unstable();
1150:         return status_query_refusal(&format!(
1151:             "-Status and -Wait take only -Task, -CollabDir, -Id, -Prune (with -Status) and -WaitTimeoutSec (with -Wait); not -{}.",
1152:             extra.join(", -")
1153:         ));
1154:     }
1155:     if o.prune && o.wait {
1156:         return status_query_refusal(
1157:             "-Prune goes with -Status, not with -Wait (-Status -Prune is the one form that writes: it deletes old files).",
1158:         );
1159:     }
1160:     if o.wait_timeout_sec_given {
1161:         if !o.wait {
1162:             return status_query_refusal("-WaitTimeoutSec goes with -Wait.");
1163:         }
1164:         if o.wait_timeout_sec <= 0 {
1165:             return status_query_refusal(&format!(
1166:                 "-WaitTimeoutSec must be greater than 0 (got {}); leave it out for the run's own budget.",
1167:                 o.wait_timeout_sec
1168:             ));
1169:         }
1170:     }
1171:     if o.task.is_empty() || !c3_core::task_slug::is_slug(&o.task) {
1172:         return status_query_refusal(
1173:             "-Task must be a slug (letters, digits, dot, dash, underscore).",
1174:         );
1175:     }
1176:     let want = o.id.trim().to_lowercase();
1177:     if o.id_given && !is_id_prefix(&want) {
1178:         return status_query_refusal(&format!(
1179:             "-Id takes a detach id or its beginning (hexadecimal, as -Detach printed it); got '{}'.",
1180:             o.id
1181:         ));
1182:     }
1183:     let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
1184:     let repo_root = providers::resolve_repo_root(&cwd);
1185:     let collab_root = providers::resolve_collab_root(&repo_root, &o.collab_dir);
1186:     // -CollabDir given but missing: the id of a detached run goes with -Id (a bare positional id
1187:     // binds to -CollabDir).
1188:     if o.collab_dir != ".collab" && !collab_root.is_dir() {
1189:         return status_query_refusal(&format!(
1190:             "-CollabDir '{}' does not exist ({}); the id of a detached run goes with -Id (-Status -Id <id8>).",
1191:             o.collab_dir,
1192:             collab_root.display()
1193:         ));
1194:     }
1195:     let task_dir = collab_root.join(&o.task);
1196: 
1197:     let select = |want: &str| -> Vec<RunEntry> {
1198:         let w8: String = {
1199:             let mut s = want.replace('-', "");
1200:             if s.len() > 8 {
1201:                 s.truncate(8);
1202:             }
1203:             s
1204:         };
1205:         read_detached_runs(&task_dir)
1206:             .into_iter()
1207:             .filter(|r| {
1208:                 if want.is_empty() {
1209:                     return true;
1210:                 }
1211:                 if !r.id8.starts_with(&w8) {
1212:                     return false;
1213:                 }
1214:                 if want.len() > 8 {
1215:                     return r
1216:                         .record
1217:                         .as_ref()
1218:                         .map(|rec| rec.id.to_lowercase().starts_with(want))
1219:                         .unwrap_or(false);
1220:                 }
1221:                 true
1222:             })
1223:             .collect()
1224:     };
1225: 
1226:     let mut runs = select(&want);
1227:     if !want.is_empty() {
1228:         if runs.is_empty() {
1229:             let all = read_detached_runs(&task_dir);
1230:             let known: Vec<String> = all.iter().map(|r| r.id8.clone()).collect();
1231:             return status_query_refusal(&format!(
1232:                 "no detached run of task '{}' has an id starting with '{want}' ({}).",
1233:                 o.task,
1234:                 if known.is_empty() {
1235:                     "it has none".to_string()
1236:                 } else {
1237:                     format!("its detached runs: {}", known.join(", "))
1238:                 }
1239:             ));
1240:         }
1241:         if runs.len() > 1 {
1242:             return status_query_refusal(&format!(
1243:                 "-Id '{want}' matches {} detached runs of task '{}': {}; give more of the id.",
1244:                 runs.len(),
1245:                 o.task,
1246:                 runs.iter()
1247:                     .map(|r| r.id8.clone())
1248:                     .collect::<Vec<_>>()
1249:                     .join(", ")
1250:             ));
1251:         }
1252:     }
1253: 
1254:     if o.prune {
1255:         prune(&runs);
1256:         runs = select(&want);
1257:     }
1258: 
1259:     let mut timed_out = false;
1260:     let mut wait_limit = 0i64;
1261:     let mut limit_text = String::new();
1262:     if o.wait {
1263:         let is_open = |r: &RunEntry| {
1264:             matches!(
1265:                 judge(r, Utc::now()).state.as_str(),
1266:                 "running" | "starting" | "elsewhere"
1267:             )
1268:         };
1269:         let waiting_ids: Vec<String> = runs
1270:             .iter()
1271:             .filter(|r| is_open(r))
1272:             .map(|r| r.id8.clone())
1273:             .collect();
1274:         if !waiting_ids.is_empty() {
1275:             if o.wait_timeout_sec > 0 {
1276:                 wait_limit = o.wait_timeout_sec;
1277:                 limit_text = "-WaitTimeoutSec".into();
1278:             } else {
1279:                 wait_limit = runs
1280:                     .iter()
1281:                     .filter(|r| waiting_ids.contains(&r.id8))
1282:                     .map(|r| r.record.as_ref().map(|x| x.budget_sec).unwrap_or(0))
1283:                     .max()
1284:                     .unwrap_or(0);
1285:                 if wait_limit <= 0 {
1286:                     wait_limit = 3600;
1287:                 }
1288:                 limit_text = format!(
1289:                     "the budget of the run{}",
1290:                     if waiting_ids.len() > 1 { "s" } else { "" }
1291:                 );
1292:             }
1293:             println!(
1294:                 "{TOOL}: waiting for {} detached run{} of task '{}' ({}) - up to {wait_limit} s ({limit_text}), checking every 2 s",
1295:                 waiting_ids.len(),
1296:                 if waiting_ids.len() != 1 { "s" } else { "" },
1297:                 o.task,
1298:                 waiting_ids.join(", ")
1299:             );
1300:             let watch = Instant::now();
1301:             loop {
1302:                 runs = select(&want);
1303:                 let still: Vec<&RunEntry> = runs
1304:                     .iter()
1305:                     .filter(|r| waiting_ids.contains(&r.id8) && is_open(r))
1306:                     .collect();
1307:                 if still.is_empty() {
1308:                     break;
1309:                 }
1310:                 let left = wait_limit as f64 - watch.elapsed().as_secs_f64();
1311:                 if left <= 0.0 {
1312:                     timed_out = true;
1313:                     break;
1314:                 }
1315:                 let ms = (left * 1000.0).clamp(100.0, 2000.0) as u64;
1316:                 std::thread::sleep(std::time::Duration::from_millis(ms));
1317:             }
1318:         }
1319:     }
1320: 
1321:     if runs.is_empty() {
1322:         println!(
1323:             "{TOOL}: no detached consultation in task '{}' ({}).",
1324:             o.task,
1325:             task_dir.display()
1326:         );
1327:         return 0;
1328:     }
1329:     let now = Utc::now();
1330:     write_report(&runs, now);
1331:     if timed_out {
1332:         println!();
1333:         println!(
1334:             "{TOOL}: still running after {wait_limit} s ({limit_text}); the run was not touched - -Wait again, or -Status later."
1335:         );
1336:         return 3;
1337:     }
1338:     // The worst state decides: 2 running > 1 failed/died > 0 all done and usable.
1339:     let mut worst = 0;
1340:     for r in &runs {
1341:         let e = judge(r, now).exit;
1342:         if e > worst {
1343:             worst = e;
1344:         }
1345:     }
1346:     worst
1347: }
