391: /// `home_dir` is used only for `codex_config` `~` expansion.
392: pub fn validate_roster(path: &str, text: &str, home_dir: Option<&str>) -> Roster {
393:     let mut r = Roster {
394:         exists: true,
395:         path: path.to_string(),
396:         ..Default::default()
397:     };
398:     let data: Value = match serde_json::from_str(text) {
399:         Ok(v) => v,
400:         Err(e) => {
401:             r.error = roster_refusal(
402:                 path,
403:                 &format!("it does not parse: {}", crate::one_line(&e.to_string())),
404:             );
405:             return r;
406:         }
407:     };
408:     let obj = match data.as_object() {
409:         Some(o) => o,
410:         None => {
411:             r.error = roster_refusal(path, "the top level is not a JSON object");
412:             return r;
413:         }
414:     };
415:     let mut why = String::new();
416:     for key in obj.keys() {
417:         if !["roster_version", "reviewers", "parallel", "require", "ext"].contains(&key.as_str()) {
418:             why = format!("unknown key '{key}' at the top level (allowed: roster_version, reviewers, parallel, require, ext)");
419:             break;
420:         }
421:     }
422:     // (wave 26, D12) top-level ext: validated as an object only (checked before roster_version,
423:     // matching the plugin's order so the same refusal wins when several keys are wrong).
424:     if why.is_empty() {
425:         if let Some(xv) = obj.get("ext") {
426:             if !xv.is_object() {
427:                 why = format!(
428:                     "ext must be an object (the extension point of other implementations; got {})",
429:                     compact(xv)
430:                 );
431:             }
432:         }
433:     }
434:     if why.is_empty() {
435:         match obj.get("roster_version") {
436:             None => why = "roster_version is missing (expected 1)".into(),
437:             Some(v) if !is_json_integer(v) || v.as_i64() != Some(1) => {
438:                 why = format!("roster_version must be 1 (got {})", compact(v));
439:             }
440:             _ => {}
441:         }
442:     }
443:     if why.is_empty() {
444:         match obj.get("reviewers") {
445:             None => why = "reviewers is missing".into(),
446:             Some(v) if !v.is_array() => why = "reviewers is not an array".into(),
447:             Some(v) if v.as_array().unwrap().is_empty() => why = "reviewers is empty".into(),
448:             _ => {}
449:         }
450:     }
451:     let mut entries: Vec<RosterEntry> = Vec::new();
452:     if why.is_empty() {
453:         let reviewers = obj["reviewers"].as_array().unwrap();
454:         for (idx, item) in reviewers.iter().enumerate() {
455:             let pos = idx + 1;
456:             let at = format!("entry {pos}");
457:             let iobj = match item.as_object() {
458:                 Some(o) => o,
459:                 None => {
460:                     why = format!("{at} is not an object");
461:                     break;
462:                 }
463:             };
464:             for key in iobj.keys() {
465:                 if ![
466:                     "provider",
467:                     "model",
468:                     "codex_config",
469:                     "auth",
470:                     // (0.6.0, wave 29b E1/E5) the claude engine's endpoint block (refused below on
471:                     // every entry C3 can run) and the plan of any entry
472:                     "endpoint",
473:                     "plan",
474:                     "panel",
475:                     "engine",
476:                     "lab",
477:                     "roles",
478:                     "timeout_sec",
479:                     "stall_sec",
480:                     "context_tokens",
481:                     "ext",
482:                 ]
483:                 .contains(&key.as_str())
484:                 {
485:                     why = format!(
486:                         "{at} has an unknown key '{key}' (allowed: provider, model, codex_config, auth, endpoint, plan, panel, engine, lab, roles, timeout_sec, stall_sec, context_tokens, ext)"
487:                     );
488:                     break;
489:                 }
490:             }
491:             if !why.is_empty() {
492:                 break;
493:             }
494:             // (wave 26b, D3 / F22-2, F22-4) the matcher's and the seed's delimiters never
495:             // inside a provider label, a model or an engine: '::', '[', ']', '|', ',', '#'.
496:             // (0.6.0, wave 29) a claude model may end with the 1M-context suffix [1m] - the rest
497:             // obeys the rule.
498:             let is_claude_item = iobj.get("engine").and_then(|v| v.as_str()) == Some("claude");
499:             let strip_1m = strip_1m_suffix;
500:             let mut d3_bad = false;
501:             for sk in ["provider", "model", "engine"] {
502:                 if let Some(sv) = iobj.get(sk).and_then(|v| v.as_str()) {
503:                     let sv = if sk == "model" && is_claude_item {
504:                         strip_1m(sv)
505:                     } else {
506:                         sv.to_string()
507:                     };
508:                     if let Some(bad) = roster_string_problem(&sv) {
509:                         why = format!("roster entry #{pos}: {sk} must not contain '{bad}'");
510:                         d3_bad = true;
511:                         break;
512:                     }
513:                 }
514:             }
515:             if d3_bad {
516:                 break;
517:             }
518:             // (wave 26b, D11) timeout_sec: an integer from 60 to 86400 (seconds). The three numeric
519:             // keys come first, then ext and the plan - the plugin's per-entry order (0.6.0).
520:             let mut timeout_sec: i64 = 0;
